WITH base AS (SELECT * FROM order_items WHERE unit_price BETWEEN 190 AND 300), OrderIdSummary AS (SELECT order_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(unit_price) AS unit_price_count FROM base GROUP BY order_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) SELECT order_id, quantity_bucket, unit_price_count FROM OrderIdSummary ORDER BY 2, order_id LIMIT 5;
